3|namespace App\Models;
4|
5|use App\Enums\AttendanceStatus;
6|use App\Enums\EnrollmentStatus;
7|use Illuminate\Database\Eloquent\Factories\HasFactory;
8|use Illuminate\Database\Eloquent\Model;
9|use Illuminate\Database\Eloquent\Relations\BelongsTo;
10|
11|/**
12| * حضور و غیاب یک دانش‌آموز در یک جلسه.
13| *
14| * یکتایی روی (جلسه، دانش‌آموز) در پایگاه داده است: فرم گروهی «همه حاضر» روی
15| * کل کلاس اجرا می‌شود و اجرای دوبارهٔ آن نباید رکورد تکراری بسازد.
16| */
17|class Attendance extends Model
18|{
19|    use HasFactory;
20|
21|    protected $fillable = [
22|        'class_session_id',
23|        'student_id',
24|        'status',
25|        'arrival_minute',
26|        'notes',
27|    ];
28|
29|    protected function casts(): array
30|    {
31|        return [
32|            'status' => AttendanceStatus::class,
33|            'arrival_minute' => 'integer',
34|        ];
35|    }
36|
37|    public function classSession(): BelongsTo
38|    {
39|        return $this->belongsTo(ClassSession::class);
40|    }
41|
42|    public function student(): BelongsTo
43|    {
44|        return $this->belongsTo(Student::class);
45|    }
46|
47|    public function statusLabel(): string
48|    {
49|        return $this->status?->label() ?? '—';
50|    }
51|
52|    public function arrivalLabel(): ?string
53|    {
54|        if ($this->arrival_minute === null) {
55|            return null;
56|        }
57|
58|        return sprintf('%02d:%02d', intdiv($this->arrival_minute, 60), $this->arrival_minute % 60);
59|    }
60|
61|    public function attended(): bool
62|    {
63|        return $this->status?->attended() ?? false;
64|    }
65|
66|    /**
67|     * ثبت حضور برای یک جلسه، با یک سطر به ازای هر دانش‌آموز.
68|     *
69|     * updateOrCreate به‌جای create عمدی است: اپراتور ممکن است دکمهٔ «همه حاضر»
70|     * را روی جلسه‌ای بزند که نیمی‌اش ثبت شده، و آن نیمی نباید رکورد تکراری
71|     * بسازد یا دست‌کم ثبت‌های دستی‌اش را پاک کند.
72|     *
73|     * @param  iterable<int, array{student_id: int, status?: string, arrival_minute?: int|null, notes?: string|null}>  $rows
74|     * @return int تعداد سطرهای نوشته‌شده
75|     */
76|    public static function recordFor(ClassSession $session, iterable $rows): int
77|    {
78|        $written = 0;
79|
80|        foreach ($rows as $row) {
81|            self::updateOrCreate(
82|                [
83|                    'class_session_id' => $session->id,
84|                    'student_id' => $row['student_id'],
85|                ],
86|                [
87|                    'status' => $row['status'] ?? AttendanceStatus::Present->value,
88|                    'arrival_minute' => $row['arrival_minute'] ?? null,
89|                    'notes' => $row['notes'] ?? null,
90|                ],
91|            );
92|
93|            $written++;
94|        }
95|
96|        return $written;
97|    }
98|
99|    /** «همه حاضر» برای کل دانش‌آموزان ثبت‌نام‌شدهٔ قطعیِ این جلسه. */
100|    public static function markAllPresent(ClassSession $session): int
101|    {
102|        // فقط کسانی که هنوز ثبت نشده‌اند. «همه حاضر» یک دکمهٔ گروهی است و نباید
103|        // غیبتی را که اپراتور دستی ثبت کرده پاک کند — از دست دادن یک ثبت
104|        // دستی با یک کلیک، بدترین حالت ممکن است.
105|        $studentIds = $session->course->enrollments()
106|            ->where('status', EnrollmentStatus::Confirmed->value)
107|            ->whereNotIn('student_id', self::query()
108|                ->where('class_session_id', $session->id)
109|                ->select('student_id'))
110|            ->pluck('student_id')
111|            ->all();
112|
113|        return self::recordFor($session, array_map(
114|            fn (int $studentId) => ['student_id' => $studentId],
115|            $studentIds,
116|        ));
117|    }
118|
119|    /**
120|     * درصد حضور یک دانش‌آموز در یک دوره.
121|     *
122|     * غیبت موجه از صورت‌کسر بیرون می‌ماند: حضوری که هرگز برگزار نشده نباید
123|     * درصد دانش‌آموز را خراب کند. اگر همهٔ جلسات موجه باشند، تقسیم بر صفر
124|     * می‌شود و درصد «صفر» یا «صد» دروغ می‌گفت.
125|     */
126|    public static function attendanceRateFor(Student $student, Course $course): ?float
127|    {
128|        $rows = self::query()
129|            ->where('student_id', $student->id)
130|            ->whereHas('classSession', fn ($q) => $q->where('course_id', $course->id))
131|            ->get();
132|
133|        $counted = $rows->filter(fn (self $row) => $row->status->countsTowardRate());
134|
135|        if ($counted->isEmpty()) {
136|            return null;
137|        }
138|
139|        $attended = $counted->filter(fn (self $row) => $row->attended())->count();
140|
141|        return round($attended / $counted->count() * 100, 2);
142|    }
