/**
 * ساخت ردیف‌های کارنامهٔ رسمی یک دانش‌آموز.
 * ...
 */
class TranscriptBuilder
{
    public function __construct(private readonly WeightedAverage $average = new WeightedAverage) {}
```
PHP 8.5 supports `new` in initializers — yes (8.1+). But property promotion with default new in initializer is allowed for readonly properties? `new` in parameter default is allowed for non-static expressions since 8.1, and readonly promoted property with default — the default is evaluated... it's fine. But simpler: just `new WeightedAverage` inside methods to match repo style (repo does `new WeightedAverage` in views).

Let's write:

```php
class TranscriptBuilder
{
    /** @return array{rows: list<array{...}>, totals: array{...}} */
    public function build(Student $student): array
    {
        $average = new WeightedAverage;

        $rows = $student->enrollments()
            ->whereIn('status', [...])
            ->with('course.subject')
            ->get()
            ->map(function ($enrollment) use ($student, $average) {
                $course = $enrollment->course;
                $score = $average->finalScore($student, $course);
                return [
                    'enrollment' => $enrollment,
                    'course' => $course,
                    'grades' => Grade::forStudentInCourse($student, $course)->sortBy([['type','asc'],['title','asc']])->values(),
                    'score' => $score,
                    'hours' => $course->totalHours(),
                    'rate' => Attendance::attendanceRateFor($student, $course),
                    'passed' => $score === null ? null : $score >= Setting::passMark(),
                ];
            })
            ->values()
            ->all();

        return ['rows' => $rows, 'totals' => $this->totals($rows)];
    }

    private function totals(array $rows): array
    {
        $scores = array_filter(array_column($rows, 'score'), fn($s) => $s !== null);
        $graded = count($scores);
        return [
            'courses' => count($rows),
            'graded' => $graded,
            'hours' => array_sum(array_column($rows,'hours')),
            'average' => $graded ? round(array_sum($scores)/$graded, 2) : null,
            'passed' => count(array_filter(array_column($rows,'passed'), fn($p)=>$p===true)),
            'has_record' => $graded > 0,
        ];
    }
}
```

