namespace App\Services;

use App\Enums\EnrollmentStatus;
use App\Models\Attendance;
use App\Models\Grade;
use App\Models\Setting;
use App\Models\Student;

/**
 * ردیف‌های کارنامهٔ رسمی یک دانش‌آموز (شماره 37).
 *
 * سند رسمی است، پس چیزی که چاپ می‌شود باید همان چیزی باشد که صفحهٔ پرونده
 * نشان می‌دهد: همان ثبت‌نام‌ها، همان نمرهٔ نهایی وزنی، همان درصد حضور. دو
 * محاسبهٔ جدا برای یک عدد واحد یعنی دو سندِ ناسازگار با هم.
 *
 * ثبت‌نام لغوشده در سند نمی‌آید: «این آدم آمد و رفت» سابقه است، نه کارنامه.
 */
class TranscriptBuilder
{
    /**
     * @return array{
     *     rows: list<array{
     *         enrollment: \App\Models\CourseEnrollment,
     *         course: \App\Models\Course,
     *         grades: \Illuminate\Support\Collection,
     *         score: float|null,
     *         hours: float,
     *         rate: float|null,
     *         passed: bool|null,
     *     }>,
     *     totals: array{
     *         courses: int,
     *         hours: float,
     *         average: float|null,
     *         passed: int,
     *         has_record: bool,
     *     }
     * }
     */
    public function build(Student $student): array
    {
        $average = new WeightedAverage;

        $rows = $student->enrollments()
            ->whereIn('status', [
                EnrollmentStatus::Confirmed->value,
                EnrollmentStatus::Pending->value,
                EnrollmentStatus::Waitlisted->value,
            ])
            ->with('course.subject')
            ->get()
            ->map(function ($enrollment) use ($student, $average) {
                $course = $enrollment->course;
                $score = $average->finalScore($student, $course);

                return [
                    'enrollment' => $enrollment,
                    'course' => $course,
                    'grades' => Grade::forStudentInCourse($student, $course)
                        ->sortBy([['type', 'asc'], ['title', 'asc']])
                        ->values(),
                    'score' => $score,
                    'hours' => $course->totalHours(),
                    'rate' => Attendance::attendanceRateFor($student, $course),
                    'passed' => $score === null ? null : $score >= Setting::passMark(),
                ];
            })
            ->values()
            ->all();

        return [
            'rows' => $rows,
            'totals' => $this->totals($rows),
        ];
    }

    /**
     * جمع‌های سند: تعداد دوره‌ها، ساعت، میانگین و تعداد قبولی‌ها.
     *
     * میانگین فقط روی دوره‌های دارای نمره حساب می‌شود. دورهٔ بدون نمره را
     * صفر فرض کردن یعنی میانگین دانش‌آموزی که هنوز نمره‌اش ثبت نشده با نمرهٔ
     * صفر مساوی شود — و سند رسمی چنین عددی را نباید بگوید.
     *
     * @param  list<array{score: float|null, hours: float, passed: bool|null}>  $rows
     * @return array{courses: int, hours: float, average: float|null, passed: int, has_record: bool}
     */
    private function totals(array $rows): array
    {
        $scores = array_values(array_filter(
            array_column($rows, 'score'),
            fn ($score) => $score !== null,
        ));

        $graded = count($scores);

        return [
            'courses' => count($rows),
            'hours' => round(array_sum(array_column($rows, 'hours')), 2),
            'average' => $graded === 0
                ? null
                : round(array_sum($scores) / $graded, 2),
            'passed' => count(array_filter(
                array_column($rows, 'passed'),
                fn ($passed) => $passed === true,
            )),
            'has_record' => $graded > 0,
        ];
    }
}
