{"content":"<?php

namespace App\Http\Controllers;

use App\Models\Student;
use App\Services\TranscriptBuilder;
use Illuminate\Contracts\View\View;

/**
 * کارنامهٔ رسمی چاپی (شماره 37).
 *
 * مثل چاپ فاکتور و فیش حقوقی: view جدا بدون layout پنل، چون منو و سایهٔ
 * پنل روی سندی که امضا می‌شود نباید بیفتد.
 */
class TranscriptController extends Controller
{
    public function print(Student $student, TranscriptBuilder $builder): View
    {
        return view('students.print.transcript', [
            'student' => $student,
            'transcript' => $builder->build($student),
            'issuedAt' => now(),
        ]);
    }
}
