{"content":"<?php

namespace Tests\Feature;

use App\Enums\GradeType;
use App\Enums\Role;
use App\Models\Course;
use App\Models\CourseEnrollment;
use App\Models\Grade;
use App\Models\Setting;
use App\Models\Student;
use App\Models\User;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Tests\TestCase;

/*
||---------------------------------------------------------------------------
|| کارنامهٔ رسمی (شماره 37)
||
|| سند رسمی است، پس سه چیز باید اثبات شود:
||   ۱. بدون منوی پنل چاپ می‌شود، با سربرگ آموزشگاه، تاریخ شمسی، ارقام فارسی
||      و محل امضا — چیزی که امضا می‌شود باید سند باشد نه صفحهٔ وب.
||   ۲. اعدادش از همان محاسبهٔ صفحهٔ پرونده می‌آیند: نمرهٔ نهایی وزنی، جمع
||      ساعت، و میانگینی که دورهٔ بدون نمره را صفر حساب نمی‌کند.
||   ۳. برای دانش‌آموز بدون نمره هم صادر می‌شود («فاقد سابقه») و خطا نمی‌دهد؛
||      سندِ ندادن یعنی پاسخِ «نداریم» به جایِ «هنوز نشده».
||
|| دسترسی: همان نقش‌هایی که بخش نمره را می‌بینند (Role::sections). امور مالی
|| و پذیرش صفحهٔ دانش‌آموز را باز می‌کنند ولی نمره کار آن‌ها نیست.
*/

class TranscriptTest extends TestCase
{
    use RefreshDatabase;

    private function actingAsRole(Role $role): User
    {
        $user = User::factory()->role($role)->create();

        $this->actingAs($user);

        return $user;
    }

    /**
     * دانش‌آموز ثبت‌نام‌شدهٔ قطعی در یک دورهٔ مشخص.
     *
     * @param  array<string, mixed>  $courseAttributes
     * @return array{0: Student, 1: Course}
     */
    private function enrolled(array $courseAttributes = []): array
    {
        $course = Course::factory()->create($courseAttributes);
        $student = Student::factory()->create();

        CourseEnrollment::enroll($student, $course)->confirm();

        return [$student, $course];
    }

    // ── چاپ ────────────────────────────────────────────────

    public function test_the_transcript_is_printed_without_the_panel_chrome(): void
    {
        $this->actingAsRole(Role::Admin);
        Setting::put(Setting::ACADEMY_NAME, 'آموزشگاه نمونه');

        [$student] = $this->enrolled();

        $response = $this->get(route('students.transcript', $student));

        $response->assertOk();
        // منو و سایهٔ پنل روی سندی که امضا می‌شود نباید باشند
        $response->assertDontSee('drawer');
        $response->assertSee('کارنامهٔ رسمی')
            ->assertSee('آموزشگاه نمونه')
            ->assertSee($student->full_name)
            ->assertSee('امضای دانش‌آموز')
            ->assertSee('امضای مدیر آموزشگاه');
    }

    public function test_the_issue_date_is_shamsi_and_the_national_code_is_persian(): void
    {
        $this->actingAsRole(Role::Deputy);

        [$student] = $this->enrolled([
            'session_count' => 10,
            'session_duration' => 60,
        ]);

        $this->get(route('students.transcript', $student))
            ->assertOk()
            ->assertSee('تاریخ صدور: '.jalali_date(now()))
            ->assertSee(to_persian_digits($student->national_code))
            ->assertDontSee($student->national_code);

        // تاریخ تولد هم شمسی است، نه میلادی ذخیره‌شده در دیتابیس
        $this->assertStringNotContainsString(
            $student->birth_date->toDateString(),
            $this->get(route('students.transcript', $student))->getContent(),
        );
    }

    // ── اعداد ──────────────────────────────────────────────

    public function test_the_final_score_and_the_pass_status_come_from_the_weighted_average(): void
    {
        $this->actingAsRole(Role::Admin);

        [$student, $course] = $this->enrolled([
            'session_count' => 10,
            'session_duration' => 60,
        ]);

        Grade::record($student, $course, GradeType::Final, 'پایان‌ترم', 16);

        $response = $this->get(route('students.transcript', $student));

        $response->assertOk()
            ->assertSee(to_persian_digits('16.00'))
            ->assertSee('قبول')
            ->assertSee(to_persian_digits('10.0'))
            // جمع ساعت: ۱۰ جلسهٔ ۶۰ دقیقه‌ای
            ->assertSee(to_persian_digits('10.0'));
    }

    public function test_a_score_below_the_pass_mark_is_printed_as_rejected(): void
    {
        $this->actingAsRole(Role::Admin);

        [$student, $course] = $this->enrolled();

        Grade::record($student, $course, GradeType::Final, 'پایان‌ترم', 8);

        $this->get(route('students.transcript', $student))
            ->assertOk()
            ->assertSee('مردود')
            ->assertDontSee('>قبول<');
    }

    public function test_the_average_skips_courses_without_grades(): void
    {
        $this->actingAsRole(Role::Admin);

        // دورهٔ اول نمرهٔ ۱۶ دارد، دورهٔ دوم هنوز نمره‌ای ندارد. اگر دورهٔ
        // دوم صفر حساب شود میانگین ۸ می‌شود و سند رسمی عددِ غلط می‌گوید
        [$student, $graded] = $this->enrolled();
        [, $ungraded] = $this->enrolled();

        Grade::record($student, $graded, GradeType::Final, 'پایان‌ترم', 16);

        $response = $this->get(route('students.transcript', $student));

        $response->assertOk()
            ->assertSee(to_persian_digits('16.00'))
            ->assertSee('میانگین کل')
            ->assertSee(to_persian_digits('2'));

        $this->assertSame(2, substr_count($response->getContent(), $ungraded->title));
    }

    public function test_the_breakdown_of_each_grade_is_on_the_document(): void
    {
        $this->actingAsRole(Role::Admin);

        [$student, $course] = $this->enrolled();

        Grade::record($student, $course, GradeType::Homework, 'تکلیف اول', 18, gradedAt: '2026-11-01');
        Grade::record($student, $course, GradeType::Final, 'پایان‌ترم', 14);

        $this->get(route('students.transcript', $student))
            ->assertOk()
            ->assertSee('ریزنمرات')
            ->assertSee('تکلیف «تکلیف اول»')
            ->assertSee(to_persian_digits('18.00').'/'.to_persian_digits('20.00'))
            // تاریخ نمره هم شمسی است
            ->assertSee(jalali_date('2026-11-01'));
    }

    public function test_a_cancelled_enrollment_is_not_on_the_transcript(): void
    {
        $this->actingAsRole(Role::Admin);

        $course = Course::factory()->create();
        $student = Student::factory()->create();
        CourseEnrollment::enroll($student, $course)->cancel();

        $this->get(route('students.transcript', $student))
            ->assertOk()
            ->assertDontSee($course->title);
    }

    // ── دانش‌آموز بدون نمره ────────────────────────────────

    public function test_a_student_without_any_grade_still_gets_a_document(): void
    {
        $this->actingAsRole(Role::Admin);

        [$student] = $this->enrolled();

        $response = $this->get(route('students.transcript', $student));

        // خطا نمی‌دهد و سندِ خالی هم صادر می‌شود
        $response->assertOk()
            ->assertSee('فاقد سابقه')
            ->assertSee('کارنامهٔ رسمی')
            ->assertSee($student->full_name);

        $this->assertSame(0, substr_count($response->getContent(), 'مردود'));
    }

    public function test_a_student_with_no_enrolment_gets_a_document_that_says_so(): void
    {
        $this->actingAsRole(Role::Admin);

        $student = Student::factory()->create();

        $this->get(route('students.transcript', $student))
            ->assertOk()
            ->assertSee('در هیچ دوره‌ای ثبت‌نام نکرده است')
            ->assertSee('فاقد سابقه');
    }

    // ── دسترسی ────────────────────────────────────────────

    public function test_finance_and_reception_cannot_open_a_transcript(): void
    {
        [$student] = $this->enrolled();

        foreach ([Role::Finance, Role::Reception] as $role) {
            $this->actingAsRole($role);

            $this->get(route('students.transcript', $student))->assertForbidden();
        }
    }

    public function test_a_teacher_can_print_a_transcript(): void
    {
        $this->actingAsRole(Role::Teacher);

        [$student] = $this->enrolled();

        $this->get(route('students.transcript', $student))->assertOk();
    }

    public function test_a_guest_is_sent_to_login(): void
    {
        [$student] = $this->enrolled();

        $this->get(route('students.transcript', $student))
            ->assertRedirect(route('login'));
    }

    public function test_the_link_is_offered_only_to_roles_that_see_grades(): void
    {
        [$student] = $this->enrolled();

        $this->actingAsRole(Role::Deputy);
        $this->get(route('students.show', $student))
            ->assertOk()
            ->assertSee('کارنامهٔ رسمی');

        $this->actingAsRole(Role::Reception);
        $this->get(route('students.show', $student))
            ->assertOk()
            ->assertDontSee('کارنامهٔ رسمی');

        $this->actingAsRole(Role::Finance);
        $this->get(route('students.show', $student))
            ->assertOk()
            ->assertDontSee('کارنامهٔ رسمی');
    }
}
