{"new_string":"    public function test_the_final_score_and_the_pass_status_come_from_the_weighted_average(): void
    {
        $this->actingAsRole(Role::Admin);

        [$student, $course] = $this->enrolled([
            'session_count' => 10,
            'session_duration' => 60,
        ]);

        Grade::record($student, $course, GradeType::Final, 'پایان‌ترم', 16);

        $response = $this->get(route('students.transcript', $student));
        $response->assertOk()->assertSee(to_persian_digits('16.00'));

        $content = $response->getContent();

        // وضعیت قبولی در همان ستون وضعیت است، نه در برچسب «نمرهٔ قبولی»
        $this->assertSame(1, preg_match('/<td class="status">\s*قبول\s*<\/td>/u', $content));

        // جمع ساعت: ۱۰ جلسهٔ ۶۰ دقیقه‌ای = ۱۰٫۰ ساعت
        $this->assertSame(1, preg_match('/data-summary="hours">۱۰٫۰<\/span>/u', $content));
        $this->assertSame(1, preg_match('/data-summary="pass-mark">۱۰<\/span>/u', $content));
    }

    public function test_a_score_below_the_pass_mark_is_printed_as_rejected(): void
    {
        $this->actingAsRole(Role::Admin);

        [$student, $course] = $this->enrolled();

        Grade::record($student, $course, GradeType::Final, 'پایان‌ترم', 8);

        $content = $this->get(route('students.transcript', $student))
            ->assertOk()
            ->getContent();

        $this->assertSame(1, preg_match('/<td class="status">\s*مردود\s*<\/td>/u', $content));
        $this->assertSame(0, preg_match('/<td class="status">\s*قبول\s*<\/td>/u', $content));
        $this->assertSame(1, preg_match('/data-summary="passed">۰<\/span>/u', $content));
    }

    public function test_the_average_skips_courses_without_grades(): void
    {
        $this->actingAsRole(Role::Admin);

        // دورهٔ اول نمرهٔ ۱۶ دارد، دورهٔ دوم هنوز نمره‌ای ندارد. اگر دورهٔ
        // دوم صفر حساب شود میانگین ۸ می‌شود و سند رسمی عددِ غلط می‌گوید
        [$student, $graded] = $this->enrolled(['title' => 'دورهٔ نمره‌دار']);
        [, $ungraded] = $this->enrolled(['title' => 'دورهٔ بی‌نمره']);

        Grade::record($student, $graded, GradeType::Final, 'پایان‌ترم', 16);

        $response = $this->get(route('students.transcript', $student));
        $response->assertOk();

        $content = $response->getContent();

        // میانگین فقط روی دورهٔ دارای نمره
        $this->assertSame(1, preg_match('/data-summary="average">\s*۱۶٫۰۰\s*<\/span>/u', $content));
        $this->assertSame(1, preg_match('/data-summary="courses">۲<\/span>/u', $content));

        // هر دو دوره در سند هستند، حتی آن‌که نمره ندارد
        $this->assertStringContainsString('دورهٔ نمره‌دار', $content);
        $this->assertStringContainsString('دورهٔ بی‌نمره', $content);
        $this->assertSame(1, preg_match('/<td class="status">\s*فاقد سابقه\s*<\/td>/u', $content));
    }","old_string":"    public function test_the_final_score_and_the_pass_status_come_from_the_weighted_average(): void
